package fr.gemsofrod.encyclopedie.data

/** Traductions anglaises du nom et des textes descriptifs des fossiles. */
object FossileTranslationsEn {
    val data: Map<String, FossileTranslation> = mapOf(
        "fossile-ammonite-madagascar" to FossileTranslation(
            nom = "Madagascar Ammonite",
            descriptionCourte = "The most iconic of fossils, the calcified spiral of a marine cephalopod that vanished alongside the dinosaurs.",
            descriptionLongue = "Ammonites are marine cephalopods related to today's nautilus and octopus, whose spiral-coiled shells fossilised by the million along the ancient shorelines of Cretaceous Madagascar. Sawn and polished, they reveal their internal septa (sutures) in geometric patterns prized in both décor and entry-level jewellery.",
            interetJoaillerie = "Good: polished discs set as pendants, whole specimens for décor and beginner collecting"
        ),
        "fossile-ammolite" to FossileTranslation(
            nom = "Ammolite",
            descriptionCourte = "The only fossil officially recognised as a gemstone, its iridescence rivalling that of opal.",
            descriptionLongue = "Ammolite comes from a single deposit in the world, along the St. Mary River in Alberta, where the aragonite nacre of certain giant ammonites was preserved intact rather than recrystallising into calcite. The result is a spectacular iridescence, so fine and fragile that it is almost always protected by a doublet or triplet before setting. CIBJO officially classified it as an organic gemstone in 1981, alongside pearl, coral and amber.",
            interetJoaillerie = "High: cabochons, set doublets and triplets, highly sought after for its opal-like iridescence"
        ),
        "fossile-orthocere" to FossileTranslation(
            nom = "Orthoceras",
            descriptionCourte = "A straight-shelled cephalopod in the shape of an elongated cone, a distant ancestor of the squid.",
            descriptionLongue = "Unlike the coiled ammonite, the orthoceras had a straight, chambered conical shell, within which the animal adjusted its buoyancy much as the nautilus still does today. Moroccan limestone slabs, riddled with cross-sections of orthoceras and other marine invertebrates, are widely used as polished flooring and decorative objects.",
            interetJoaillerie = "Moderate: mainly décor (slabs, sinks, trays) rather than jewellery"
        ),
        "fossile-goniatite" to FossileTranslation(
            nom = "Goniatite",
            descriptionCourte = "The direct ancestor of the ammonite, recognisable by its simpler zigzag internal septa.",
            descriptionLongue = "Appearing before the ammonites in the Devonian, goniatites share the same coiled silhouette but display simpler, saw-toothed internal suture lines. Morocco yields remarkably well-preserved specimens, often sold raw or lightly polished to reveal the shell without erasing its natural relief.",
            interetJoaillerie = "Moderate: collector pieces and raw, lightly polished pendants"
        ),
        "fossile-trilobite-elrathia" to FossileTranslation(
            nom = "Elrathia kingii Trilobite",
            descriptionCourte = "The most commonly found trilobite in the world, extracted by the million from a single Utah deposit.",
            descriptionLongue = "Elrathia kingii is a small Middle Cambrian trilobite extracted in considerable quantities from the shales of Utah's Wheeler Formation — a deposit so productive that it supplies nearly all the trilobites sold on the world market. Its characteristic three-part segmentation (cephalon, thorax, pygidium) makes it an excellent teaching specimen for understanding the anatomy of this group of arthropods, extinct since the end of the Permian.",
            interetJoaillerie = "Low: mainly collecting, occasionally mounted raw as a protected pendant"
        ),
        "fossile-trilobite-phacops" to FossileTranslation(
            nom = "Phacops rana Trilobite",
            descriptionCourte = "The collectors' star trilobite, famous for its large compound eyes with calcite facets.",
            descriptionLongue = "Phacops rana is arguably the most sought-after trilobite among collectors for its prominent hemispherical eyes, formed of dozens of individual calcite lenses — one of the very first complex optical systems in the history of evolution. Moroccan workshops in Alnif specialise in the painstaking preparation of these pieces, air-scribed free of the surrounding rock to reveal the full relief of the animal curled up in defensive position.",
            interetJoaillerie = "Low: mainly collecting and décor"
        ),
        "fossile-trilobite-calymene" to FossileTranslation(
            nom = "Calymene Trilobite",
            descriptionCourte = "A classic and affordable trilobite, often found curled up like a fossilised woodlouse.",
            descriptionLongue = "The genus Calymene, widespread in Moroccan deposits and long known in England under the nickname \"Dudley bug,\" is distinguished by its ability to roll completely into a ball in defensive posture, exactly like a modern woodlouse. This fossilised \"enrolled\" posture is one of the most common introductory specimens for beginner collectors.",
            interetJoaillerie = "Low: collecting and décor"
        ),
        "fossile-dent-megalodon" to FossileTranslation(
            nom = "Megalodon Tooth",
            descriptionCourte = "The tooth of the largest shark ever to have existed, which could exceed 18 cm in height.",
            descriptionLongue = "Megalodon, a giant shark that went extinct around 3.6 million years ago, could reach 15 to 18 metres in length. Its massive triangular teeth, serrated like those of today's great white shark but far larger, mineralised in the sediment and took on varied hues depending on the deposit. The finest pieces, symmetrical and unworn, command high prices both among collectors and in raw jewellery.",
            interetJoaillerie = "High: raw pendants set in prong mounts, much sought after in decorative jewellery"
        ),
        "fossile-os-dinosaure-gembone" to FossileTranslation(
            nom = "Agatized Dinosaur Bone (\"Gembone\")",
            descriptionCourte = "A dinosaur bone entirely replaced, molecule by molecule, by coloured agate.",
            descriptionLongue = "In certain Jurassic deposits of the American West, buried dinosaur bones underwent complete silicification: the original bone material dissolved and was progressively replaced by coloured silica, faithfully preserving the porous cellular structure of the bone while transforming it into polishable agate. The result, nicknamed \"gembone\" by lapidaries, combines the scientific value of an authentic dinosaur fossil with the aesthetic appeal of a semi-precious stone bearing unique patterns.",
            interetJoaillerie = "High: highly sought-after cabochons, a unique cellular pattern impossible to imitate"
        ),
        "fossile-poisson-green-river" to FossileTranslation(
            nom = "Green River Fossil Fish",
            descriptionCourte = "Entire shoals of small fish frozen in an exceptionally fine lacustrine limestone.",
            descriptionLongue = "Wyoming's ancient Fossil Lake preserved, in finely laminated sediments, tens of thousands of freshwater fish in an exceptional state of conservation — scales, fins and sometimes even stomach contents intact. The Green River Formation is today one of the most prolific vertebrate fossil deposits in the world, quarried in the open air and sold as sawn slabs for décor.",
            interetJoaillerie = "Moderate: framed slabs, decorative objects rather than jewellery"
        ),
        "fossile-dent-mosasaure" to FossileTranslation(
            nom = "Mosasaur Tooth",
            descriptionCourte = "The conical tooth of a great predatory marine reptile, a distant cousin of today's monitor lizards.",
            descriptionLongue = "Mosasaurs were large predatory marine reptiles, related to today's monitor lizards, that dominated the seas at the very end of the Cretaceous, just before the extinction that also wiped out the non-avian dinosaurs. The Moroccan phosphate deposits of Khouribga, world-renowned for their wealth of fossil marine vertebrates, regularly yield well-preserved conical teeth, prized by collectors for their striking shape.",
            interetJoaillerie = "Moderate: raw pendants, strong collector value"
        ),
        "fossile-ivoire-mammouth" to FossileTranslation(
            nom = "Fossil Mammoth Ivory",
            descriptionCourte = "The ivory of a vanished ice-age giant, uncovered by the thawing of the Siberian permafrost.",
            descriptionLongue = "The gradual warming of the Siberian permafrost releases woolly mammoth tusks every year, some remarkably well preserved after tens of thousands of years buried in ice. This legal and regulated trade, unlike modern elephant ivory, supplies carvers and jewellers with a material whose texture and grain closely resemble living ivory, sometimes enhanced by spectacular blue-green tones caused by surface mineralisation with iron phosphate (vivianite).",
            interetJoaillerie = "High: sculptures, jewellery, inlays — a legally regulated trade, unlike present-day elephant ivory"
        ),
        "fossile-bois-petrifie" to FossileTranslation(
            nom = "Petrified Wood",
            descriptionCourte = "An entire tree trunk turned to stone, ring by ring, through silica infiltration.",
            descriptionLongue = "When a fallen trunk becomes rapidly buried in silica-saturated sediment, silicate-rich water gradually infiltrates the wood's cellular structure and replaces it, fibre by fibre, before decomposition can erase it. The result preserves the texture, growth rings and sometimes even the insect borings in the bark, while acquiring the hardness and polish of agate — hence its popularity in both jewellery and large decorative furnishings.",
            interetJoaillerie = "High: cabochons and jewellery, also much sought after for décor (trays, tabletops)"
        ),
        "fossile-fougere" to FossileTranslation(
            nom = "Fossil Fern",
            descriptionCourte = "The delicate carbon imprint of a fern from the vast swamp forests of the Carboniferous.",
            descriptionLongue = "The vast forested swamps of the Carboniferous, source of most of today's coal deposits, left countless imprints of ferns and seed ferns in their clay shales, preserved as a thin carbon film. These slabs, obtained by splitting the rock along the plane of the fossilised leaf, reveal veining of remarkable fineness for plants more than 300 million years old.",
            interetJoaillerie = "Low: mainly collecting and framed wall décor"
        ),
        "fossile-ambre-baltique" to FossileTranslation(
            nom = "Baltic Amber",
            descriptionCourte = "The fossilised resin of vanished conifer forests, the oldest organic gemstone in human jewellery.",
            descriptionLongue = "Baltic amber formed around 44 million years ago from the resin of giant, now-extinct conifers whose forests once covered northern Europe. Carried by rivers and then cast up on the shores of the Baltic Sea after storms, it has been worked and traded by humans since the Bronze Age — amber trade routes rank among the oldest documented trading networks in Europe.",
            interetJoaillerie = "High: traditional Northern European jewellery since the Bronze Age"
        ),
        "fossile-ambre-inclusion" to FossileTranslation(
            nom = "Amber with Insect Inclusion",
            descriptionCourte = "A mosquito, an ant or a flower frozen for eternity in a drop of resin turned to stone.",
            descriptionLongue = "Dominican amber, younger and generally more transparent than Baltic amber, owes its fame to the exceptional richness of its inclusions: insects, spiders, small flowers and even, occasionally, small vertebrates are found trapped with a wealth of detail that has made this fossil famous well beyond collector circles, popularised in particular by fiction surrounding DNA preserved in amber.",
            interetJoaillerie = "High: each inclusion is unique, adding strong value in collector jewellery"
        ),
        "fossile-copal" to FossileTranslation(
            nom = "Copal",
            descriptionCourte = "The \"teenage\" stage of amber: a fossil resin too young to have fully polymerised.",
            descriptionLongue = "Copal is a plant resin that has not yet completed the slow chemical polymerisation that, over millions of years, transforms resin into true amber. Softer, more soluble in solvents and often more transparent, it is sometimes wrongly sold as amber — a simple acetone test (which makes copal tacky on the surface, with no effect on true amber) distinguishes the two.",
            interetJoaillerie = "Moderate: local artisanal jewellery, to be clearly distinguished from amber on any sales listing"
        ),
        "fossile-corail-agatise" to FossileTranslation(
            nom = "Agatized Fossil Coral",
            descriptionCourte = "An entire coral reef turned to agate, each polyp frozen into a flower of silica.",
            descriptionLongue = "In Florida, ancient coral reefs became silicified by silica-rich groundwater, each coral polyp faithfully replaced by chalcedony while retaining its characteristic radiating structure. Once sliced and polished, the result evokes natural floral patterns so regular that it is sometimes mistaken for an artificial creation — it was designated the official state stone of Florida in 1979.",
            interetJoaillerie = "High: cabochons with unique floral patterns, prized in both regional and international jewellery"
        ),
        "fossile-oursin" to FossileTranslation(
            nom = "Fossil Sea Urchin",
            descriptionCourte = "The perfectly symmetrical calcareous test of a sea urchin, long worn as a talisman.",
            descriptionLongue = "Fossil sea urchin tests (shells), with their characteristic five-fold radial symmetry, are found in abundance in the Cretaceous chalks of Europe and North Africa. Nicknamed \"fairy loaves\" or \"Saint Peter's stones\" in European folklore, they were traditionally kept as good-luck charms or household protection long before being studied scientifically.",
            interetJoaillerie = "Low to moderate: traditionally worn as a raw pendant (a \"Saint Peter's stone\" or \"fairy loaf\" in Europe)"
        ),
        "fossile-crinoide" to FossileTranslation(
            nom = "Crinoid (Entrochite)",
            descriptionCourte = "The stacked calcareous rings of a \"sea lily's\" stem, a fixed echinoderm rather than a plant.",
            descriptionLongue = "Despite its misleading name of \"sea lily,\" the crinoid is an echinoderm animal related to sea urchins and starfish, anchored to the seabed by a long, jointed stem. This stem, made of calcareous rings stacked like coins, disarticulates easily after the animal's death and is found in abundance in certain limestones, forming what geologists call crinoidal limestone once polished into slabs.",
            interetJoaillerie = "Moderate: slabs and decorative objects rather than jewellery, occasionally cabochons for isolated stem segments"
        ),
        "fossile-stromatolite" to FossileTranslation(
            nom = "Fossil Stromatolite",
            descriptionCourte = "The oldest known traces of life on Earth, built layer by layer by colonies of bacteria.",
            descriptionLongue = "Stromatolites are not the remains of an individual organism but laminated sedimentary structures, patiently built layer upon layer by colonies of cyanobacteria trapping sediment and precipitating calcium carbonate. Some Australian deposits are among the oldest traces of life identified on Earth, at more than 3.4 billion years old — a direct testimony to the planet's very first ecosystems, today polished into decorative slabs for its unique concentric pattern.",
            interetJoaillerie = "Low to moderate: decorative slabs, occasional cabochons for silicified varieties"
        ),
        "fossile-belemnite" to FossileTranslation(
            nom = "Belemnite",
            descriptionCourte = "The fossilised \"guard\" of a prehistoric squid, long mistaken in folklore for a thunderbolt stone.",
            descriptionLongue = "What is found fossilised is not the whole animal but its guard, a rigid internal calcareous structure that served as a counterweight and support for the soft body of the cephalopod, an extinct cousin of today's squid. Its elongated conical shape, often mistaken in European popular folklore for a \"thunderbolt stone\" fallen from the sky, makes it an easily recognisable fossil even for non-specialists.",
            interetJoaillerie = "Low: collecting, occasional raw pendants"
        )
    )
}
